import React from 'react';
import clsx from 'clsx';
import './AcidBorderBeam.css';

export interface AcidBorderBeamProps {
    size?: number;
    duration?: number;
    delay?: number;
    colorFrom?: string;
    colorTo?: string;
    borderThickness?: number;
    className?: string;
}

export const AcidBorderBeam = ({
    size = 150,
    duration = 8,
    delay = 0,
    colorFrom = 'var(--ac-brand)',
    colorTo = '#ec4899',
    borderThickness = 2,
    className
}: AcidBorderBeamProps) => {
    return (
        <div
            className={clsx('ac-border-beam', className)}
            style={{
                '--size': `${size}px`,
                '--duration': `${duration}s`,
                '--delay': `${delay}s`,
                '--color-from': colorFrom,
                '--color-to': colorTo,
                '--thickness': `${borderThickness}px`,
            } as React.CSSProperties}
        />
    );
};

.ac-border-beam {
    pointer-events: none;
    position: absolute;
    inset: 0;
    border: var(--thickness) solid transparent;
    border-radius: inherit;
    mask-clip: padding-box, border-box;
    mask-composite: intersect;
    mask-image: linear-gradient(transparent, transparent), linear-gradient(#000, #000);
}

.ac-border-beam::after {
    content: "";
    position: absolute;
    aspect-ratio: 1;
    width: var(--size);
    background: linear-gradient(to left, var(--color-from), var(--color-to), transparent);
    offset-path: rect(0 auto auto 0 round var(--size));
    animation: border-beam-anim var(--duration) linear infinite;
    animation-delay: var(--delay);
}

@keyframes border-beam-anim {
    to {
        offset-distance: 100%;
    }
}
